<template><view class="page"><view class="page-head"><text class="eyebrow">TRAVEL INFO</text><view class="page-title">发布车辆</view><text class="muted">补充司机、时间和上车点，方便大家准时集合。</text></view><view class="card form-card"><view class="field"><text class="field-label">车牌号</text><input v-model="form.plateNumber" class="input" placeholder="请输入车牌号" /></view><view class="field"><text class="field-label">司机姓名</text><input v-model="form.driverName" class="input" placeholder="请输入司机姓名" /></view><view class="field"><text class="field-label">上车时间</text><input v-model="form.pickupTime" class="input" placeholder="2026-09-01T08:30" /></view><view class="field"><text class="field-label">上车地点</text><input v-model="form.pickupLocation" class="input" placeholder="请输入集合地点" /></view><button class="primary-btn" @click="submit">发布车辆信息</button></view></view></template>
<script setup lang="ts">import{reactive,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{api}from'@/services/api';import{apiTime}from'@/utils/time';const id=ref(0),form=reactive({plateNumber:'',driverName:'',pickupTime:'',pickupLocation:''});onLoad((o:any)=>id.value=Number(o.id));async function submit(){if(Object.values(form).some(v=>!v))return uni.showToast({title:'请填写完整信息',icon:'none'});await api(`/activities/${id.value}/vehicles`,'POST',{...form,pickupTime:apiTime(form.pickupTime)});uni.showToast({title:'发布成功'});setTimeout(()=>uni.navigateBack(),500)}</script>
